def manage_scene(action, name, path, build_index, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0053000" if __import__("os").path.isdir("./environment_mix/0053000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    ops_file = "unity_operations_and_console.json"
    projects_file = "unity_projects.json"
    assets_file = "unity_assets.json"
    scenes_file = "unity_scenes.json"

    ops = _load(ops_file)
    projects = _load(projects_file)
    assets = _load(assets_file)
    scenes = _load(scenes_file)

    def _log(proj_id, result_obj, op_status):
        latency_ms = int((time.time() - t0) * 1000)
        op_row = {
            "id": "ump_op_" + uuid.uuid4().hex,
            "project_id": proj_id or "unknown",
            "row_type": "operation",
            "tool_name": "manage_scene",
            "action": action if isinstance(action, str) else None,
            "request": {"action": action, "name": name, "path": path, "build_index": build_index},
            "result": result_obj,
            "status": op_status,
            "started_at": now,
            "completed_at": now,
            "wait_for_completion": True,
            "menu_path": None,
            "menu_parameters": None,
            "console_type": None,
            "message": None,
            "stacktrace": None,
            "timestamp": now,
            "created_at": now,
            "updated_at": now,
            "_latency_ms": latency_ms,
        }
        if isinstance(ops, list):
            ops.append(op_row)
            _save(ops_file, ops)

    def _pick_project():
        if not isinstance(projects, list) or not projects:
            return None
        # Prefer a project that has scenes/assets (serve the call) and is active/disconnected
        candidates = []
        for p in projects:
            if not isinstance(p, dict) or not p.get("id"):
                continue
            if p.get("status") not in ("active", "disconnected"):
                continue
            pid = p["id"]
            has_scene = any(isinstance(s, dict) and s.get("project_id") == pid for s in (scenes if isinstance(scenes, list) else []))
            if has_scene:
                return p
            candidates.append(p)
        return candidates[0] if candidates else (projects[0] if isinstance(projects[0], dict) else None)

    def _norm_asset_path(pth):
        if not isinstance(pth, str):
            return None
        p = pth.strip().replace("\\", "/")
        p = re.sub(r"/{2,}", "/", p)
        return p

    def _ensure_assets_prefix(p):
        if p is None:
            return None
        if not p.startswith("Assets/"):
            return None
        return p

    def _find_scene_by_name_path(pid, scene_name, scene_path):
        if not isinstance(scenes, list):
            return None
        for s in scenes:
            if not isinstance(s, dict):
                continue
            if s.get("project_id") != pid:
                continue
            if s.get("scene_name") == scene_name and s.get("path") == scene_path:
                return s
        return None

    def _find_scene_by_build_index(pid, idx):
        if not isinstance(scenes, list):
            return None
        for s in scenes:
            if not isinstance(s, dict):
                continue
            if s.get("project_id") != pid:
                continue
            if s.get("build_index") == idx and s.get("is_in_build") is True:
                return s
        return None

    def _new_id(prefix):
        return prefix + uuid.uuid4().hex

    proj = _pick_project()
    project_id = proj.get("id") if isinstance(proj, dict) else None
    if not project_id:
        out = _err("UNAUTHORIZED", "No project context available to serve this request")
        _log(None, out, "failed")
        return out

    if not isinstance(action, str) or not action.strip():
        out = _err("VALIDATION_ERROR", "action must be a non-empty string", field="action")
        _log(project_id, out, "failed")
        return out
    action = action.strip()

    allowed_actions = {"create", "load", "save"}
    if action not in allowed_actions:
        out = _err("VALIDATION_ERROR", "Unsupported action", allowed_actions=sorted(allowed_actions))
        _log(project_id, out, "failed")
        return out

    # Parameter handling: tool schema marks name/path/build_index as required, but real behavior is action-specific.
    # Validate types when provided; require what the business rule needs.
    if name is not None and not (isinstance(name, str) and name.strip()):
        out = _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")
        _log(project_id, out, "failed")
        return out
    if path is not None and not (isinstance(path, str) and path.strip()):
        out = _err("VALIDATION_ERROR", "path must be a non-empty string", field="path")
        _log(project_id, out, "failed")
        return out
    if build_index is not None and not isinstance(build_index, int):
        out = _err("VALIDATION_ERROR", "build_index must be an integer", field="build_index")
        _log(project_id, out, "failed")
        return out

    scene_name = name.strip() if isinstance(name, str) else None
    scene_path = _ensure_assets_prefix(_norm_asset_path(path)) if isinstance(path, str) else None

    # For create/load/save, require name+path, unless build_index is explicitly being used (load/save allowed by rule only when provided and in build).
    use_build_index = build_index is not None

    if use_build_index:
        if build_index < 0:
            out = _err("VALIDATION_ERROR", "build_index must be >= 0", field="build_index")
            _log(project_id, out, "failed")
            return out
    else:
        if not scene_name or not scene_path:
            out = _err("VALIDATION_ERROR", "name and path are required unless build_index is provided; path must start with 'Assets/'", rule="manage_scene targets scene by (project_id, scene_name, path) or by build_index")
            _log(project_id, out, "failed")
            return out

    # Locate target scene
    scene_row = None
    if use_build_index:
        scene_row = _find_scene_by_build_index(project_id, build_index)
        if scene_row is None:
            out = _err("NOT_FOUND", "Scene not found for build_index where is_in_build=true", build_index=build_index)
            _log(project_id, out, "failed")
            return out
    else:
        scene_row = _find_scene_by_name_path(project_id, scene_name, scene_path)
        if scene_row is None and action != "create":
            out = _err("NOT_FOUND", "Scene not found for given name/path", name=scene_name, path=scene_path)
            _log(project_id, out, "failed")
            return out

    # Mutations
    if action == "create":
        if scene_row is not None:
            out = _err("CONFLICT", "Scene already exists for given name/path", name=scene_name, path=scene_path)
            _log(project_id, out, "failed")
            return out

        # Ensure unique constraints: (project_id, path) and (project_id, scene_name)
        for s in scenes if isinstance(scenes, list) else []:
            if not isinstance(s, dict) or s.get("project_id") != project_id:
                continue
            if s.get("path") == scene_path:
                out = _err("CONFLICT", "Scene path already exists in project", path=scene_path)
                _log(project_id, out, "failed")
                return out
            if s.get("scene_name") == scene_name:
                out = _err("CONFLICT", "Scene name already exists in project", name=scene_name)
                _log(project_id, out, "failed")
                return out

        # Create backing asset of type 'scene' if not present
        asset_row = None
        if isinstance(assets, list):
            for a in assets:
                if isinstance(a, dict) and a.get("project_id") == project_id and a.get("path") == scene_path:
                    asset_row = a
                    break
        if asset_row is None:
            # ensure assets unique(project_id, path)
            if isinstance(assets, list):
                for a in assets:
                    if isinstance(a, dict) and a.get("project_id") == project_id and a.get("path") == scene_path:
                        out = _err("CONFLICT", "Asset already exists at path", path=scene_path)
                        _log(project_id, out, "failed")
                        return out
            asset_row = {
                "id": "ump_ast_" + uuid.uuid4().hex[:26],
                "project_id": project_id,
                "path": scene_path,
                "name": scene_name,
                "asset_type": "scene",
                "guid": None,
                "status": "present",
                "properties": None,
                "preview_blob_ref": None,
                "last_imported_at": None,
                "last_modified_at": now,
                "created_at": now,
                "updated_at": now,
            }
            if not isinstance(assets, list):
                assets = []
            assets.append(asset_row)
            _save(assets_file, assets)
        else:
            # Validate the backing asset is scene type
            if asset_row.get("asset_type") != "scene":
                out = _err("CONFLICT", "Existing asset at path is not a scene asset", path=scene_path, asset_type=asset_row.get("asset_type"))
                _log(project_id, out, "failed")
                return out
            if asset_row.get("status") == "deleted":
                out = _err("INVALID_TRANSITION", "Cannot create scene: backing asset is deleted", path=scene_path)
                _log(project_id, out, "failed")
                return out

        new_scene = {
            "id": "ump_scn_" + uuid.uuid4().hex[:26],
            "project_id": project_id,
            "asset_id": asset_row["id"],
            "scene_name": scene_name,
            "path": scene_path,
            "build_index": None,
            "is_in_build": False,
            "is_loaded": False,
            "is_dirty": False,
            "hierarchy_snapshot": None,
            "status": "available",
            "last_saved_at": None,
            "created_at": now,
            "updated_at": now,
        }
        if not isinstance(scenes, list):
            scenes = []
        scenes.append(new_scene)
        _save(scenes_file, scenes)

        out = {"scene": new_scene}
        _log(project_id, out, "succeeded")
        return out

    # For load/save, ensure status available
    if scene_row.get("status") != "available":
        out = _err("NOT_FOUND", "Scene is not available", scene_id=scene_row.get("id"), status=scene_row.get("status"))
        _log(project_id, out, "failed")
        return out

    if action == "load":
        # Set is_loaded true for that scene; optionally set others false (not specified), so only ensure this one true.
        changed = False
        for s in scenes if isinstance(scenes, list) else []:
            if not isinstance(s, dict):
                continue
            if s.get("id") == scene_row.get("id"):
                if s.get("is_loaded") is not True:
                    s["is_loaded"] = True
                    s["updated_at"] = now
                    changed = True
                scene_row = s
        # Update project active_scene_id
        for p in projects if isinstance(projects, list) else []:
            if isinstance(p, dict) and p.get("id") == project_id:
                if p.get("active_scene_id") != scene_row.get("id"):
                    p["active_scene_id"] = scene_row.get("id")
                    p["updated_at"] = now
                    changed = True
        if not changed:
            # idempotent: still "has effect" conceptually; but state already matches.
            out = {"scene": scene_row, "project_active_scene_id": scene_row.get("id")}
            _log(project_id, out, "succeeded")
            return out
        _save(scenes_file, scenes)
        _save(projects_file, projects)
        out = {"scene": scene_row, "project_active_scene_id": scene_row.get("id")}
        _log(project_id, out, "succeeded")
        return out

    if action == "save":
        # Save sets dirty false and last_saved_at now
        changed = False
        for s in scenes if isinstance(scenes, list) else []:
            if not isinstance(s, dict):
                continue
            if s.get("id") == scene_row.get("id"):
                if s.get("is_dirty") is not False:
                    s["is_dirty"] = False
                    changed = True
                s["last_saved_at"] = now
                s["updated_at"] = now
                changed = True
                scene_row = s
        if not changed:
            out = _err("NOT_FOUND", "Scene not found to save", scene_id=scene_row.get("id"))
            _log(project_id, out, "failed")
            return out
        _save(scenes_file, scenes)
        out = {"scene": scene_row}
        _log(project_id, out, "succeeded")
        return out

    out = _err("VALIDATION_ERROR", "Unsupported action", allowed_actions=sorted(allowed_actions))
    _log(project_id, out, "failed")
    return out

def read_console(action=None, types=None, count=None, filter_text=None, since_timestamp=None, format=None, include_stacktrace=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0053000" if __import__("os").path.isdir("./environment_mix/0053000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _pick_project_id():
        projects = _load("unity_projects.json")
        for st in ("active", "disconnected"):
            for pr in projects:
                if pr.get("status") == st:
                    return pr.get("id")
        for pr in projects:
            if pr.get("id"):
                return pr.get("id")
        return None

    def _parse_iso(ts):
        if ts is None:
            return None
        if not isinstance(ts, str) or not ts.strip():
            return "invalid"
        s = ts.strip()
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
                return dt
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return "invalid"

    def _log_op(project_id, action_name, request_payload, result_payload, op_status):
        ops = _load("unity_operations_and_console.json")
        op_row = {
            "id": "op_" + uuid.uuid4().hex,
            "project_id": project_id,
            "row_type": "operation",
            "tool_name": "read_console",
            "action": action_name,
            "request": request_payload,
            "result": result_payload,
            "status": op_status,
            "started_at": None,
            "completed_at": None,
            "wait_for_completion": None,
            "menu_path": None,
            "menu_parameters": None,
            "console_type": None,
            "message": None,
            "stacktrace": None,
            "timestamp": now,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op_row)
        _save("unity_operations_and_console.json", ops)
        return op_row

    project_id = _pick_project_id()
    if not project_id:
        return _err("UNAUTHORIZED", "No Unity project context available")

    if action is None:
        action = "get"
    if not isinstance(action, str):
        req = {"action": action, "types": types, "count": count, "filter_text": filter_text, "since_timestamp": since_timestamp,
               "format": format, "include_stacktrace": include_stacktrace}
        result = _err("VALIDATION_ERROR", "action must be a string")
        _log_op(project_id, str(action), req, result, "failed")
        return result
    if action not in {"get", "clear"}:
        req = {"action": action, "types": types, "count": count, "filter_text": filter_text, "since_timestamp": since_timestamp,
               "format": format, "include_stacktrace": include_stacktrace}
        result = _err("VALIDATION_ERROR", "action must be 'get' or 'clear'")
        _log_op(project_id, action, req, result, "failed")
        return result

    req_payload = {"action": action, "types": types, "count": count, "filter_text": filter_text, "since_timestamp": since_timestamp,
                   "format": format, "include_stacktrace": include_stacktrace}

    ops = _load("unity_operations_and_console.json")

    if action == "clear":
        # remove console messages for project
        before = len(ops)
        new_ops = [r for r in ops if not (r.get("project_id") == project_id and r.get("row_type") == "console_message")]
        removed = before - len(new_ops)
        if removed == 0:
            result = _err("NOT_FOUND", "No console messages to clear")
            _log_op(project_id, action, req_payload, result, "failed")
            return result
        _save("unity_operations_and_console.json", new_ops)
        result = {"success": True, "data": {"cleared": removed}}
        _log_op(project_id, action, req_payload, result, "succeeded")
        return result

    # GET
    if types is None:
        types = ["all"]
    if not isinstance(types, list) or any(not isinstance(x, str) for x in types):
        result = _err("VALIDATION_ERROR", "types must be an array of strings")
        _log_op(project_id, action, req_payload, result, "failed")
        return result

    allowed_types = {"error", "warning", "log", "all"}
    if any(t not in allowed_types for t in types):
        result = _err("VALIDATION_ERROR", "types contains unknown value", allowed=list(sorted(allowed_types)))
        _log_op(project_id, action, req_payload, result, "failed")
        return result

    if count is None:
        count_v = 50
    else:
        if not isinstance(count, int):
            result = _err("VALIDATION_ERROR", "count must be an integer")
            _log_op(project_id, action, req_payload, result, "failed")
            return result
        count_v = count
    if count_v < 1:
        result = _err("VALIDATION_ERROR", "count must be >= 1")
        _log_op(project_id, action, req_payload, result, "failed")
        return result
    if count_v > 1000:
        result = _err("VALIDATION_ERROR", "count must be <= 1000")
        _log_op(project_id, action, req_payload, result, "failed")
        return result

    if filter_text is not None and not isinstance(filter_text, str):
        result = _err("VALIDATION_ERROR", "filter_text must be a string or null")
        _log_op(project_id, action, req_payload, result, "failed")
        return result

    if include_stacktrace is None:
        include_stacktrace = False
    if not isinstance(include_stacktrace, bool):
        result = _err("VALIDATION_ERROR", "include_stacktrace must be boolean")
        _log_op(project_id, action, req_payload, result, "failed")
        return result

    since_dt = None
    if since_timestamp is not None:
        parsed = _parse_iso(since_timestamp)
        if parsed == "invalid":
            result = _err("VALIDATION_ERROR", "since_timestamp must be ISO 8601 timestamp string")
            _log_op(project_id, action, req_payload, result, "failed")
            return result
        since_dt = parsed

    want_all = "all" in types
    want_types = {"error", "warning", "log"} if want_all else set(types)

    rows = []
    for r in ops:
        if r.get("project_id") != project_id:
            continue
        if r.get("row_type") != "console_message":
            continue
        if r.get("status") != "recorded":
            continue
        ct = r.get("console_type")
        if ct not in want_types:
            continue
        if since_dt is not None:
            ts = r.get("timestamp")
            if not isinstance(ts, str) or not ts:
                continue
            p = _parse_iso(ts)
            if p == "invalid" or p <= since_dt:
                continue
        if filter_text:
            txt = filter_text.lower()
            m = (r.get("message") or "").lower()
            st = (r.get("stacktrace") or "").lower()
            if txt not in m and txt not in st:
                continue
        rows.append(r)

    # newest first
    def _k(x):
        return x.get("timestamp") or x.get("created_at") or ""
    rows.sort(key=_k, reverse=True)
    rows = rows[:count_v]

    # format output
    if format is None:
        format = "json"
    if not isinstance(format, str):
        result = _err("VALIDATION_ERROR", "format must be a string or null")
        _log_op(project_id, action, req_payload, result, "failed")
        return result
    if format not in {"json", "text"}:
        result = _err("VALIDATION_ERROR", "format must be 'json' or 'text'")
        _log_op(project_id, action, req_payload, result, "failed")
        return result

    if format == "text":
        lines = []
        for r in rows:
            base = f"[{r.get('timestamp')}] {r.get('console_type')}: {r.get('message') or ''}"
            if include_stacktrace and r.get("stacktrace"):
                base += "\n" + r.get("stacktrace")
            lines.append(base)
        out = {"success": True, "data": {"text": "\n\n".join(lines), "count": len(rows)}}
    else:
        msgs = []
        for r in rows:
            item = {
                "id": r.get("id"),
                "type": r.get("console_type"),
                "message": r.get("message"),
                "timestamp": r.get("timestamp"),
            }
            if include_stacktrace:
                item["stacktrace"] = r.get("stacktrace")
            msgs.append(item)
        out = {"success": True, "data": {"messages": msgs, "count": len(msgs)}}

    _log_op(project_id, action, req_payload, out, "succeeded")
    return out

def execute_menu_item(menu_path, action=None, parameters=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0053000" if __import__("os").path.isdir("./environment_mix/0053000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _pick_project_id():
        projects = _load("unity_projects.json")
        for st in ("active", "disconnected"):
            for pr in projects:
                if pr.get("status") == st:
                    return pr.get("id")
        for pr in projects:
            if pr.get("id"):
                return pr.get("id")
        return None

    def _append_op(project_id, request_payload, result_payload, op_status):
        ops = _load("unity_operations_and_console.json")
        op_row = {
            "id": "op_" + uuid.uuid4().hex,
            "project_id": project_id,
            "row_type": "operation",
            "tool_name": "execute_menu_item",
            "action": request_payload.get("action"),
            "request": request_payload,
            "result": result_payload,
            "status": op_status,
            "started_at": None,
            "completed_at": None,
            "wait_for_completion": None,
            "menu_path": request_payload.get("menu_path"),
            "menu_parameters": request_payload.get("parameters"),
            "console_type": None,
            "message": None,
            "stacktrace": None,
            "timestamp": now,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op_row)
        _save("unity_operations_and_console.json", ops)
        return op_row

    project_id = _pick_project_id()
    if not project_id:
        return _err("UNAUTHORIZED", "No Unity project context available")

    if not isinstance(menu_path, str) or not menu_path.strip():
        req = {"menu_path": menu_path, "action": action if action is not None else "execute", "parameters": parameters}
        result = _err("VALIDATION_ERROR", "menu_path must be a non-empty string")
        _append_op(project_id, req, result, "failed")
        return result

    if action is None:
        action = "execute"
    if not isinstance(action, str):
        req = {"menu_path": menu_path, "action": action, "parameters": parameters}
        result = _err("VALIDATION_ERROR", "action must be a string")
        _append_op(project_id, req, result, "failed")
        return result
    if action != "execute":
        req = {"menu_path": menu_path, "action": action, "parameters": parameters}
        result = _err("VALIDATION_ERROR", "action must be 'execute'")
        _append_op(project_id, req, result, "failed")
        return result

    if parameters is not None and not isinstance(parameters, dict):
        req = {"menu_path": menu_path, "action": action, "parameters": parameters}
        result = _err("VALIDATION_ERROR", "parameters must be an object or null")
        _append_op(project_id, req, result, "failed")
        return result

    req_payload = {"menu_path": menu_path, "action": action, "parameters": parameters}

    # Append operation row as the primary observable effect
    op_stub_result = {"success": True, "data": {"queued": True}}
    op_row = _append_op(project_id, req_payload, op_stub_result, "queued")

    # Simulate immediate completion (server-side) by transitioning queued->running->succeeded
    ops = _load("unity_operations_and_console.json")
    for r in ops:
        if r.get("id") == op_row.get("id"):
            r["status"] = "running"
            r["started_at"] = now
            r["updated_at"] = now
            break
    _save("unity_operations_and_console.json", ops)

    completed = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    ops = _load("unity_operations_and_console.json")
    for r in ops:
        if r.get("id") == op_row.get("id"):
            r["status"] = "succeeded"
            r["completed_at"] = completed
            r["updated_at"] = completed
            r["result"] = {"success": True, "data": {"executed": True, "menu_path": menu_path, "parameters": parameters}}
            op_row = r
            break
    _save("unity_operations_and_console.json", ops)

    return {"success": True, "data": {"operation": op_row}}

def list_projects(status=None, tag=None, page_size=None, page_number=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0053000" if __import__("os").path.isdir("./environment_mix/0053000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _pick_project_id_for_logging():
        projects = _load("unity_projects.json")
        for st in ("active", "disconnected", "archived"):
            for pr in projects:
                if pr.get("status") == st and pr.get("id"):
                    return pr.get("id")
        return None

    def _log_op(project_id, request_payload, result_payload, op_status):
        ops = _load("unity_operations_and_console.json")
        op_row = {
            "id": "op_" + uuid.uuid4().hex,
            "project_id": project_id,
            "row_type": "operation",
            "tool_name": "list_projects",
            "action": "list",
            "request": request_payload,
            "result": result_payload,
            "status": op_status,
            "started_at": None,
            "completed_at": None,
            "wait_for_completion": None,
            "menu_path": None,
            "menu_parameters": None,
            "console_type": None,
            "message": None,
            "stacktrace": None,
            "timestamp": now,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op_row)
        _save("unity_operations_and_console.json", ops)

    if status is None:
        status = "all"
    if not isinstance(status, str):
        pid = _pick_project_id_for_logging() or "unknown_project"
        req = {"status": status, "tag": tag, "page_size": page_size, "page_number": page_number}
        result = _err("VALIDATION_ERROR", "status must be a string")
        _log_op(pid, req, result, "failed")
        return result

    allowed_status = {"active", "disconnected", "archived", "all"}
    if status not in allowed_status:
        pid = _pick_project_id_for_logging() or "unknown_project"
        req = {"status": status, "tag": tag, "page_size": page_size, "page_number": page_number}
        result = _err("VALIDATION_ERROR", "Unknown status filter", allowed=list(sorted(allowed_status)))
        _log_op(pid, req, result, "failed")
        return result

    if tag is not None and not isinstance(tag, str):
        pid = _pick_project_id_for_logging() or "unknown_project"
        req = {"status": status, "tag": tag, "page_size": page_size, "page_number": page_number}
        result = _err("VALIDATION_ERROR", "tag must be a string or null")
        _log_op(pid, req, result, "failed")
        return result

    if page_size is None:
        page_size_v = 50
    else:
        if not isinstance(page_size, int):
            pid = _pick_project_id_for_logging() or "unknown_project"
            req = {"status": status, "tag": tag, "page_size": page_size, "page_number": page_number}
            result = _err("VALIDATION_ERROR", "page_size must be an integer")
            _log_op(pid, req, result, "failed")
            return result
        page_size_v = page_size
    if page_size_v < 1 or page_size_v > 200:
        pid = _pick_project_id_for_logging() or "unknown_project"
        req = {"status": status, "tag": tag, "page_size": page_size_v, "page_number": page_number}
        result = _err("VALIDATION_ERROR", "page_size must be between 1 and 200")
        _log_op(pid, req, result, "failed")
        return result

    if page_number is None:
        page_number_v = 1
    else:
        if not isinstance(page_number, int):
            pid = _pick_project_id_for_logging() or "unknown_project"
            req = {"status": status, "tag": tag, "page_size": page_size_v, "page_number": page_number}
            result = _err("VALIDATION_ERROR", "page_number must be an integer")
            _log_op(pid, req, result, "failed")
            return result
        page_number_v = page_number
    if page_number_v < 1:
        pid = _pick_project_id_for_logging() or "unknown_project"
        req = {"status": status, "tag": tag, "page_size": page_size_v, "page_number": page_number_v}
        result = _err("VALIDATION_ERROR", "page_number must be >= 1")
        _log_op(pid, req, result, "failed")
        return result

    projects = _load("unity_projects.json")
    rows = []
    for p in projects:
        if status != "all" and p.get("status") != status:
            continue
        if tag is not None:
            tags = p.get("tags")
            if not isinstance(tags, list) or tag not in tags:
                continue
        rows.append(p)

    # order by updated_at desc
    def _k(x):
        return x.get("updated_at") or x.get("created_at") or ""
    rows.sort(key=_k, reverse=True)

    total = len(rows)
    start = (page_number_v - 1) * page_size_v
    end = start + page_size_v
    page = rows[start:end]
    has_more = end < total
    next_cursor = None
    if has_more:
        next_cursor = {"page_number": page_number_v + 1, "page_size": page_size_v}

    result = {"success": True, "data": {"projects": page}, "meta": {"total": total, "page_size": page_size_v, "page_number": page_number_v, "has_more": has_more, "next_cursor": next_cursor}}

    pid = _pick_project_id_for_logging()
    if pid:
        _log_op(pid, {"status": status, "tag": tag, "page_size": page_size_v, "page_number": page_number_v}, result, "succeeded")
    return result
